        };
        root.Controls.Add(copy, 0, 3); ShowDetail();
    }
    private void ShowDetail() => _detail.Text = (_matrix.CurrentRow?.Tag as ActionAvailability)?.Reason
        ?? AppLocalization.T("ExecutionContext.SelectRow");
}

