        var heading = new Label { Text = caption, ForeColor = Muted, Font = new Font("Segoe UI Semibold", 8F), AutoSize = false };
        value.Font = new Font("Segoe UI Semibold", 21F); value.ForeColor = Navy; value.AutoSize = false;
