E=os.environ.copy();E.update(GIT_NO_REPLACE_OBJECTS='1',GIT_GRAFT_FILE=os.devnull,PYTHONDONTWRITEBYTECODE='1')
def git(*a):return subprocess.check_output(['git','-c','advice.graftFileDeprecated=false',*a],env=E,text=True).strip()
assert git('rev-parse','HEAD')=='7aaefdebca68eed64c8e92d7dfff7384f0a3c800'
(J/'live.json').write_text(json.dumps(dict(pid=os.getpid(),cwd=os.getcwd(),state='WAITING_LOCAL_JOBS'))+'\n')
n=1
while True:
 p=J/f'command-{n}.json'
 while not p.exists():time.sleep(.25)
 c=json.loads(p.read_text());r=dict(job=n,command_sha256=hashlib.sha256(p.read_bytes()).hexdigest())
 try:
  if c['action']=='local_job':
   if c.get('network') is not False:raise ValueError('local jobs cannot authorize network effects')
   with (J/f'command-{n}.log').open('w') as f:
    x=subprocess.run(c['argv'],env=E,stdout=f,stderr=subprocess.STDOUT,timeout=c['timeout_seconds'])
   r.update(exit_code=x.returncode,recoverable_job_error=x.returncode!=0)
  elif c['action']=='freeze':
   if git('status','--porcelain','--untracked-files=all'):raise ValueError('candidate dirty')
   r.update(exit_code=0,candidate=git('rev-parse','HEAD'),tree=git('rev-parse','HEAD^{tree}'),worker_stays_live=True)
  else:raise ValueError('unsupported job; terminal success needs separately authenticated final gate')
 except Exception as e:r.update(exit_code=1,error=str(e),recoverable_job_error=True)
